if (!sessionStorage.getItem("AUTH")) {
    window.location.href = "/logout";
  }

  let idleTime = 0;
    const MAX_IDLE_MINUTES = 60;

    function resetIdleTimer() {
      idleTime = 0;
    }

    // Events that count as activity
    window.onload = resetIdleTimer;
    document.onmousemove = resetIdleTimer;
    document.onkeydown = resetIdleTimer;
    document.onclick = resetIdleTimer;
    document.onscroll = resetIdleTimer;

    // Check every minute
    setInterval(() => {
      idleTime++;
      if (idleTime >= MAX_IDLE_MINUTES) {
        window.location.href = "/logout";
      }
    }, 60000);


$('.billingDtl').on('change', function(){
	
	$('#inv-veh').text($(this).closest('.vehicle-item').data('vehicleno'));
	$('#inv-dri').text($(this).closest('.vehicle-item').data('driver'));
	$('#inv-type').text($(this).closest('.vehicle-item').data('type'));
	$('#inv-amt').val('');
	$('#inv-frDt').val('');
	$('#inv-ToDt').val('');
	$('#inv-date').val('');
});

$('.generate-btn').on('click', function () {

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF("p", "mm", "a4");

    /* =========================
       DATA
    ========================== */
    const vehicleNo = $('#inv-veh').text();
	if(vehicleNo === "TN00XX0000")
	{
		alert('Please Select Vehicle')
		return false;
	}
    const driver = $('#inv-dri').text().replace('Driver: ', '');
    const type = $('#inv-type').text();
	const amountVal = $('#inv-amt').val();
	const amount = amountVal
	    ? `Rs. ${Number(amountVal).toFixed(2)}`
	    : "Rs. 0.00";
		if(amount === "Rs. 0.00")
		{
			alert('Please Enter Amount')
			return false;
		}
		const rawFrom = $('#inv-frDt').val();
		const rawTo   = $('#inv-ToDt').val();
		const rawInv  = $('#inv-date').val();

		if (!rawFrom || !rawTo || !rawInv || !amount) {
		    alert("Fill all billing fields");
		    return;
		}

		const fromDate = new Date(rawFrom);
		const toDate   = new Date(rawTo);

		if (fromDate > toDate) {
		    alert("From Date cannot be greater than To Date");
		    return;
		}

		/* formatted dates (DD-MM-YYYY) */
		const from = formatDateDDMMYYYY(rawFrom);
		const to   = formatDateDDMMYYYY(rawTo);
		const invoiceDate = formatDateDDMMYYYY(rawInv);
//    	const invoiceNo = "012345100";

    /* =========================
       LOGO
    ========================== */
    const logo = "data:image/png;base64,";	
    doc.addImage(logo, "PNG", 15, 0, 40, 50);

    /* =========================
       ADDRESS (RIGHT)
    ========================== */
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text("19/1 , Sanjay Gandhi Street,", 140, 15);
    doc.text("MGR Nagar,", 140, 20);
    doc.text("Chennai 78", 140, 25);

    /* =========================
       HORIZONTAL LINE
    ========================== */
    doc.setDrawColor(150);
    doc.line(15, 38, 195, 38);

    /* =========================
       INVOICE TITLE
    ========================== */
    doc.setFont("times", "normal");
    doc.setFontSize(26);
    doc.text("Invoice", 15, 55);

    /* =========================
       DATE & INVOICE NO (BOLD)
    ========================== */
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.text(`DATE : ${invoiceDate}`, 140, 52);
//    doc.text(`INVOICE NUMBER : ${invoiceNo}`, 140, 60);

    /* =========================
       TABLE SETUP
    ========================== */
    const startY = 75;
    const pageHeight = doc.internal.pageSize.height;
    const bottomMargin = 60;
    const tableHeight = pageHeight - startY - bottomMargin;

    const headerH = 14;
    const rowH = 14;

    const x = {
        start: 15,
        name: 45,
        vehicle: 80,
        type: 105,
        from: 130,
        to: 155,
        end: 195
    };

    /* =========================
       TABLE BORDER
    ========================== */
    doc.setDrawColor(0);
    doc.rect(x.start, startY, x.end - x.start, tableHeight);

    doc.line(x.name, startY, x.name, startY + tableHeight);
    doc.line(x.vehicle, startY, x.vehicle, startY + tableHeight);
    doc.line(x.type, startY, x.type, startY + tableHeight);
    doc.line(x.from, startY, x.from, startY + tableHeight);
    doc.line(x.to, startY, x.to, startY + tableHeight);

    doc.line(x.start, startY + headerH, x.end, startY + headerH);

    /* =========================
       TABLE HEADER
    ========================== */
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.text("NAME", x.start + 3, startY + 10);
    doc.text("AUTO NUMBER", x.name + 3, startY + 10);
    doc.text("TYPE", x.vehicle + 3, startY + 10);
    doc.text("FROM DATE", x.type + 3, startY + 10);
    doc.text("TO DATE", x.from + 3, startY + 10);
    doc.text("TOTAL", x.to + 6, startY + 10);

    /* =========================
       TABLE ROW
    ========================== */
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    const rowY = startY + headerH + 9;

    doc.text(driver, x.start + 3, rowY);
    doc.text(vehicleNo, x.name + 3, rowY);
    doc.text(type, x.vehicle + 3, rowY);
    doc.text(from, x.type + 3, rowY);
    doc.text(to, x.from + 3, rowY);
    doc.text(amount, x.to + 6, rowY);

    /* =========================
       WATERMARK
    ========================== */
    const watermark = "data:image/png;base64,";
    doc.setGState(new doc.GState({ opacity: 0.08 }));
    doc.addImage(watermark, "PNG", 35, 80, 140, 140);
    doc.setGState(new doc.GState({ opacity: 1 }));

    /* =========================
       FOOTER COLOR BAR
    ========================== */
    doc.setFillColor(220, 38, 38);
    doc.rect(0, pageHeight - 20, 105, 20, "F");

    doc.setFillColor(255, 204, 51);
    doc.rect(105, pageHeight - 20, 105, 20, "F");

    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.setTextColor(0);
    doc.text("SS Auto Transport", 150, pageHeight - 8);

    /* =========================
       OPEN PDF
    ========================== */
    const blob = doc.output("blob");
    const url = URL.createObjectURL(blob);
    window.open(url, "_blank");
    setTimeout(() => URL.revokeObjectURL(url), 5000);
});


function formatDateDDMMYYYY(dateStr) {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split("-");
    return `${d}-${m}-${y}`;
}


$(document).on('change', '.billingDtl', function () {
    $('.vehicle-item').removeClass('selected');
    $(this).closest('.vehicle-item').addClass('selected');
});	

$('.vehicle-item').on('click', function () {
    $(this).find('.billingDtl').prop('checked', true).trigger('change');
});

$("#searchVehicle").on("input", function () {

    let searchText = $(this).val().toLowerCase().trim();

    $(".vehicle-item").each(function () {

        let vehicleNo = $(this).data("vehicleno").toLowerCase();
        let driverName = $(this).data("driver").toLowerCase();

        if (
            vehicleNo.includes(searchText) ||
            driverName.includes(searchText)
        ) {
            $(this).show();
        } else {
            $(this).hide();
        }
    });
	const visibleCount = $(".vehicle-card:visible").length;
	$("#no-records").toggle(visibleCount === 0);
});

$('.reportBtn').on('click', function () {

    let fromDate = $('#rptFrDt').val();
    let toDate = $('#rptToDt').val();
	
	if(!fromDate){
		alert("select From Date!");
		return;
	}else if(!toDate){
		alert("select To Date!")
		return;
	}

    window.location.href =
        "/report?fromDate=" + fromDate + "&toDate=" + toDate;
});

